        \&lt;div\&gt;\&lt;span class=&quot;text-yellow-400&quot;\&gt;Nombre:\&lt;/span\&gt; JESUS ANDRES MERCADO GOMEZ\&lt;/div\&gt;

        \&lt;div\&gt;\&lt;span class=&quot;text-yellow-400&quot;\&gt;C.C.:\&lt;/span\&gt; 1.045.668.717\&lt;/div\&gt;

