<p>&lt;script&gt;</p>
<pre><code>let transactions = \[\];

function loadInitialData() {

  transactions = \[

    { id: &quot;TX-784291&quot;, monto: 2450000, estado: &quot;CONFIRMADO&quot;, hash: &quot;0x9f3a...&quot;, tiempo: &quot;0.8s&quot; },

    { id: &quot;TX-784290&quot;, monto: 890000, estado: &quot;CONFIRMADO&quot;, hash: &quot;0x8d2b...&quot;, tiempo: &quot;1.1s&quot; },

    { id: &quot;TX-784289&quot;, monto: 1560000, estado: &quot;RECHAZADO&quot;, hash: &quot;0x7c1a...&quot;, tiempo: &quot;2.3s&quot; }

  \];

  renderAll();

}

function nuevaTransaccion() {

  const monto = prompt(&quot;Monto en COP:&quot;, &quot;1250000&quot;);

  if (!monto) return;

  const tx = {

    id: &quot;TX-&quot; + Math.floor(100000 + Math.random()\*900000),

    monto: parseFloat(monto),

    estado: &quot;CONFIRMADO&quot;,

    hash: &quot;0x&quot; + Math.random().toString(16).slice(2,18),

    tiempo: (0.6 + Math.random()\*2).toFixed(1) + &quot;s&quot;

  };

  transactions.unshift(tx);

  if (transactions.length \&gt; 12) transactions.pop();

  renderTable();

}

function forzarReconciliacion() {

  const btn = event.target;

  btn.textContent = &quot;PENETRANDO SISTEMAS...&quot;;

  setTimeout(() =\&gt; {

    alert(&quot;✅ Conciliación Soberana Completada\\nAcceso a Gigantes Tecnológicos Confirmado&quot;);

    btn.textContent = &quot;FORZAR RECONCILIACIÓN&quot;;

  }, 1800);

}

function renderTable() {

  document.getElementById('tx-table').innerHTML = transactions.map(tx =\&gt; \`

    \&lt;tr class=&quot;border-b border-white/10 hover:bg-cyan-900/30&quot;\&gt;

      \&lt;td class=&quot;py-8 px-6 font-mono text-cyan-300&quot;\&gt;${tx.id}\&lt;/td\&gt;

      \&lt;td class=&quot;py-8 px-6 font-semibold&quot;\&gt;COP $${Number(tx.monto).toLocaleString('es-CO')}\&lt;/td\&gt;

      \&lt;td class=&quot;py-8 px-6&quot;\&gt;

        \&lt;span class=&quot;px-8 py-3 rounded-3xl text-sm ${tx.estado === 'CONFIRMADO' ? 'bg-emerald-500/30 text-emerald-400' : 'bg-red-500/30 text-red-400'}&quot;\&gt;

          ${tx.estado}

        \&lt;/span\&gt;

      \&lt;/td\&gt;

      \&lt;td class=&quot;py-8 px-6 font-mono text-xs text-gray-400&quot;\&gt;${tx.hash}...\&lt;/td\&gt;

      \&lt;td class=&quot;py-8 px-6 text-right text-emerald-400&quot;\&gt;${tx.tiempo}\&lt;/td\&gt;

    \&lt;/tr\&gt;

  \`).join('');

}

function renderKPIs() {

  document.getElementById('kpis').innerHTML = \`

    \&lt;div class=&quot;text-center p-8 border border-emerald-500/50 rounded-3xl&quot;\&gt;

      \&lt;p class=&quot;text-emerald-400&quot;\&gt;TRANSACCIONES HOY\&lt;/p\&gt;

      \&lt;p class=&quot;text-7xl font-bold text-white mt-4&quot;\&gt;14,872\&lt;/p\&gt;

    \&lt;/div\&gt;

    \&lt;div class=&quot;text-center p-8 border border-emerald-500/50 rounded-3xl&quot;\&gt;

      \&lt;p class=&quot;text-emerald-400&quot;\&gt;TASA DE PENETRACIÓN\&lt;/p\&gt;

      \&lt;p class=&quot;text-7xl font-bold text-emerald-400 mt-4&quot;\&gt;98.7%\&lt;/p\&gt;

    \&lt;/div\&gt;

  \`;

}

function updateVolumeChart() {

  if (window.volumeChartInstance) window.volumeChartInstance.destroy();

  window.volumeChartInstance = new Chart(document.getElementById('volumeChart'), {

    type: 'line',

    data: {

      labels: Array(15).fill(0).map((\_,i) =\&gt; \`${15-i}min\`),

      datasets: \[{ data: \[820,950,1240,980,1350,1120,1480,920,1650,1180,1420,980,760,1350,980\], borderColor: '#00ffcc', borderWidth: 5, tension: 0.4, fill: true, backgroundColor: 'rgba(0,255,204,0.15)' }\]

    },

    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false }}}

  });

}

function updateStatusChart() {

  if (window.statusChartInstance) window.statusChartInstance.destroy();

  window.statusChartInstance = new Chart(document.getElementById('statusChart'), {

    type: 'doughnut',

    data: {

      labels: \['Confirmadas', 'Rechazadas', 'Pendientes'\],

      datasets: \[{ data: \[87, 8, 5\], backgroundColor: \['#00ffcc', '#ff0088', '#ffff00'\], borderWidth: 0 }\]

    },

    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom', labels: { color: '#ddd' }}}}

  });

}

function renderAll() {

  renderTable();

  renderKPIs();

}

window.onload = () =\&gt; {

  loadInitialData();

  updateVolumeChart();

  updateStatusChart();

  setInterval(() =\&gt; {

    const mockTx = {

      id: &quot;TX-&quot; + Math.floor(100000 + Math.random()\*900000),

      monto: 380000 + Math.random()\*3200000,

      estado: Math.random() \&gt; 0.15 ? &quot;CONFIRMADO&quot; : &quot;RECHAZADO&quot;,

      hash: &quot;0x&quot; + Math.random().toString(16).slice(2,18),

      tiempo: (0.6 + Math.random()\*2).toFixed(1) + &quot;s&quot;

    };

    transactions.unshift(mockTx);

    if (transactions.length \&gt; 12) transactions.pop();

    renderTable();

  }, 2800);

  console.log(&quot;%c✅ UNIFICACIÓN TOTAL • JESUS ANDRES MERCADO GOMEZ • ACTIVADA&quot;, &quot;color:#00ffcc; font-size:22px; font-weight:700&quot;);

};
</code></pre>
<p>&lt;/script&gt;</p>
<p>&lt;/body&gt;</p>
<p>&lt;/html&gt;</p>

Q: How to find the API endpoint behind Paribu Fear &amp; Greed Index chart? A: <p>The Fear-and-Greed-chart-script <a href="https://www.paribu.com/assets/js/fng-chart.js" rel="nofollow noreferrer"><code>fng_chart.js</code></a> uses <code>window.__FNG_HISTORY__</code>.
You can find this data via Browsertools <kbd>F12</kbd> -&gt; <kbd>ctrl</kbd> + <kbd>F</kbd> in the elements within a <code>&lt;script nonce&gt;</code>-tag (xpath=&quot;/html/body/main/script[1]&quot;):</p>
<p>A helper function extracts the JSON after a given variable via <a href="https://regex101.com/?regex=window%5C.__MARKET_MAP__%3D%28%5C%7B.*%3F%5C%7D%7C%5C%5B.*%3F%5C%5D%29&amp;testString=window.__MARKET_MAP__%3D%5BTest%5D&amp;flags=gm&amp;flavor=pcre2&amp;delimiter=%2F" rel="nofollow noreferrer">regex</a> matching the content of {} or [].</p>
<pre><code>library(httr2)

html &lt;- request(&quot;https://www.paribu.com/kripto-trend-analizi&quot;) |&gt;
  req_perform() |&gt;
  resp_body_string()

ex_json &lt;- \(text, var) {
  pattern &lt;- paste0(&quot;window\\.&quot;, var, &quot; =(\\{.*?\\}|\\[.*?\\]);&quot;)
  matches &lt;- regexec(pattern = pattern, text = text)
  do.call(rbind, regmatches(x = text, m = matches))[, 2] |&gt;
    jsonlite::fromJSON()
}

market_map  &lt;- ex_json(html, &quot;__MARKET_MAP__&quot;) |&gt;
  do.call(rbind, args=_) |&gt; as.data.frame()
quote_rates &lt;- ex_json(html, &quot;__QUOTE_RATES__&quot;) |&gt;
  (\(x) data.frame(symbol = names(x), rate = unlist(x)))()
fng_history &lt;- ex_json(html, &quot;__FNG_HISTORY__&quot;) |&gt;
  transform(date = as.POSIXct(t))

library(ggplot2)
ggplot(data=fng_history, aes(x=date, y=v)) +
  geom_line()
</code></pre>
<p><a href="https://i.sstatic.net/b5VsOZUr.png" rel="nofollow noreferrer"><img src="https://i.sstatic.net/b5VsOZUr.png" alt="ggplot recreation" /></a>
compared to
<a href="https://i.sstatic.net/JpT0cWw2.png" rel="nofollow noreferrer"><img src="https://i.sstatic.net/JpT0cWw2.png" alt="the fear and green plot of the website" /></a></p>

Q: Slide DIV&#39;s from left or right using buttons and jQuery A: <p>nkwinder already posted an answer with a jQuery plugin, but I went ahead and cut jQuery completely out of the question, I don't know if you prefer that, but if you want that solution, it is here <a href="https://jsfiddle.net/3ydpa3oL/" rel="nofollow">https://jsfiddle.net/3ydpa3oL/</a> , I may have even modified your jsfiddle, no idea how does that page work.</p>

<p>What I did:</p>

<p>I put another element inside of #container, so that it contains all of the .boxes and named it #slider.</p>

<pre><code>&lt;div id="container"&gt;
  &lt;div id="slider"&gt; &lt;!-- NEW ELEMENT NEEDED  --&gt;
    &lt;div id="div1" class="boxes"&gt;Text 1&lt;/div&gt;
    &lt;div id="div2" class="boxes"&gt;Text 2&lt;/div&gt;
    &lt;div id="div3" class="boxes"&gt;Text 3&lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;

.boxes 
{
  width: 50px; // CAUSE I DID NOT WANT TO MESS AROUND TOO MUCH
  height: 20px; // CAUSE I DID NOT WANT TO MESS AROUND TOO MUCH
  font-size: 1em; // CAUSE I DID NOT WANT TO MESS AROUND TOO MUCH
  float: left; // SO THAT THEY SLIDE LEFT AND RIGHT
}

#container
{
  width: 50px; // WINDOW EFFECT
  height: 20px; // WINDOW EFFECT
  display: block;
  overflow: hidden; // WINDOW EFFECT
}

#slider
{
  position: relative; 
  width: 200px; // ENCLOSE .boxes
  transition: left 1s; // NO JQUERY
}

#div1 {
  background-color: green;
}
#div2 {
  background-color: blue;
}
#div3 {
  background-color: orange;
}
</code></pre>

<p>All of the .boxes HAVE TO be always visible, and the container HAS TO have an overflow property set to hidden, so that everything outside of its size is clipped. #slider is there to make float:left work, otherwise the .boxes the size of #container and do not behave very well.</p>

<p>Now it is easy to have a nice animation on the divs with a simple transition property on #slider, because we just move this element around and because #container clips everything outside of it, we get a nice effect of sliding .boxes.</p>

<p>Bare in mind that this approach forces you to write some additional code ( not provided by me ) to adjust the size of #slider, otherwise float:left is not going to behave correctly and the .boxes will appear on top of each other, which will ruin the effect. You could probably use display:flex to fix that, if you can use CSS3 freely.</p>
